        key: s.key,
        src: s.src,
        found: !!found[s.key],
        panel: k,
        boxStyle: 'left:' + localX(s.left - SECRET_PAD, k) + 'px;top:' +
          (s.top - SECRET_PAD) + 'px;width:' + (s.width + SECRET_PAD * 2) + 'px;height:' +
          (s.height + SECRET_PAD * 2) + 'px',
        style: 'width:' + s.width + 'px;height:' + s.height + 'px;animation-delay:' +
          (-(i * 1.7)).toFixed(2) + 's'
