  PIG_PANELS: PIG_PANELS,
  clamp01: clamp01,
  growth: growth,
  growths: growths,
  stripWidth: stripWidth,
  layout: layout,
  viewAt: viewAt,
  openView: openView,
  panelOf: panelOf,
  localX: localX,
  panelsCovering: panelsCovering,
  sliceStyle: sliceStyle,
  buildPanels: buildPanels,
  SECRET_PAD: SECRET_PAD
