  D.wxml["pages/entry/index"] = "<view class=\"stage entry\" bindtap=\"onTap\">\n  <view class=\"warm-backdrop\"></view>\n  <firework></firework>\n  <gold-dust count=\"14\"></gold-dust>\n\n  <view class=\"entry__seal {{shown ? 'is-in' : ''}}\">\n    <view class=\"entry__ring\"></view>\n    <view class=\"entry__chars\">\n      <text>年</text>\n      <text>猪</text>\n      <text>宴</text>\n    </view>\n  </view>\n\n  <view class=\"entry__sub {{shown ? 'is-in' : ''}}\">徽州年味 · 一桌好菜</view>\n  <view class=\"entry__hint\">轻触屏幕进入</view>\n  <view class=\"paper\"></view>\n</view>\n";
